from book import Chapter
c=Chapter('01')
c.src('ORIGINAL',26,replacements=[('任何理论都是建立在一套数学原理的基本规则之上的','一套试图把科学知识统一起来的理论，需要能够清楚描述对象、关系和推理的数学工具'),('终极万物理论','这种统一框架'),('一个快速有效的方法，是依靠直觉，直觉告诉我，这门学科最可能的是范畴论！','我的直觉把研究方向指向了范畴论。直觉可以帮助选择入口，接下来则要看，这个入口究竟能够让我们看见什么。')])
c.src('ORIGINAL',28,29,replacements=[('很显然，数学就是','数学的一项重要工作，就是'),('这些看起来完全不同的数学概念，却都具有相同的基本特性：复合性，结合律，恒等态射','在这些不同的结构中，都可以考察变换的复合、复合的结合律，以及不改变对象的恒等变换')])
c.add('''第一次接触这些词，可以先想一个很普通的过程。把一种表示方式转换成另一种，再把第二种转换成第三种，我们希望能够说清楚，整个过程怎样从第一种走到第三种。不同的领域会使用不同的变换，但“变换能够接在一起”这一点，可以被单独研究。

这样做并没有消除具体差别。正如研究交通网络时，可以先研究道路怎样连接，再研究道路究竟容许什么车辆通过。如果连接方式本身就有问题，换一辆更快的车也不能解决；而连接方式相同，也不意味着路面、运力和成本都相同。抽象的意义，在于使一类共同的问题能够被放到一起看清楚。''')
c.src('ORIGINAL',31,33,replacements=[('只考察最基本共性，并不关注细枝末节的特点','可以暂时抽离具体内容，考察共同的结构'),('横看都是岭状，侧看都是峰状，这就是鸟瞰视角下发现的山脉的共同特点','同一座山在不同方向下，会呈现很不一样的形状'),('不识庐山真真面目','不识庐山真面目'),('为所有学科都提供了','能够提供'),('往往能够发现','有可能发现'),('为研究带来突破','为研究提供新的线索')])
c.add('''但站得高也有代价：距离太远，会看不清细节。真正有用的统一框架，需要容许我们在两个方向之间来回走。一方面，从不同现象中抽出共同关系；另一方面，再把这些关系放回具体问题，看看重要条件有没有被遗漏。接下来从一个人人都能够想象的问题开始：一个人究竟怎样走完一段路？''')
c.heading('走完一段路，是否必须先完成无穷件事情')
c.src('ORIGINAL',37,replacements=[('其本质触及了连续性存在与离散性表示之间的矛盾','这些问题使我们注意到运动与分段描述之间的关系'),('这个问题就是芝诺悖论的一个变种','这个问题也能帮助我们理解无穷过程'),('这个问题困扰了人们很长时间，直到“极限”这个概念的出现，才将其化解并纳入严格的数学体系。','对这个问题，实数体系中的极限概念提供了严格的解释。'),('极限通过一种精妙的方式承认了无穷过程的存在，并赋予了这个无穷过程一个确定的、有限的终点，从而用离散的、可数的步骤，完美地描述了连续的、不可数的运动。','在一个收敛序列中，项可以不断变化，却越来越接近一个确定的值。借助极限，我们可以严格描述这种接近关系，而不必把“有无穷多个分段”理解成“需要无穷长的时间”。')])
c.add('''如果每秒走一米，先走半米，再走四分之一米，再走八分之一米，所需时间也相应地变成半秒、四分之一秒、八分之一秒。分段的数量没有结束，但总时间可以趋近一秒。我们把路程分成了无穷多段，并没有给每一段额外规定一个不能缩短的等待时间。

同样，0.9、0.99、0.999 是不同的有限小数，每一个都小于 1；而 0.999… 的含义，是这个无限小数所确定的实数，即这些截断值的极限。在通常的实数体系里，它就是 1。这里并没有一个“最后的 9”，也没有一个藏在所有有限位之后、仍然大于零的差额。

读者可能会问：既然每一步都有差，为什么走到无穷以后就可以说没有差？问题恰恰在于，“无穷以后”并不是序列中一个特别遥远的下一步。极限给出的，是对整个接近过程的性质描述。把它当成最后一次有限操作，就又把两种不同的对象混到一起了。''')
c.src('ORIGINAL',38,replacements=[('芝诺悖论的根源，在于外部世界物质本体的连续性（本体论）与我们大脑意识认识、分析过程的离散性（认识论）之间的矛盾','从认识方式上看，芝诺悖论提醒我们考察：外部过程与我们对过程的分割描述，是怎样联系起来的'),('本质上是将连续的世界分割成离散的概念和步骤','经常需要把世界分割成可以区别的概念和步骤'),('探测本身是一个离散的过程，获得的结果也是一个离散的结构','很多探测所留下的记录，也是有限、离散的结构'),('但人类的直觉告诉我们，物质的本质应该是连续的、一个不可分割的整体','而我们也会用连续模型描述变化。在具体问题中，怎样连接这两种描述，需要单独说明')])
c.heading('同一个事物，可以在什么意义上相同')
c.add('''一个运动过程与它的终点不是同一种对象，一份程序与它算出的结果也不是同一种对象。它们可以通过规则联系起来，但不能只因为有联系，就说它们在所有意义上相同。

这一点在数学中尤其重要。两个东西是不是“相同”，取决于我们保留什么结构、允许什么变换。拿一个泥做的杯子和一个泥做的圆环来想象，如果只关心它们都有一个贯通的洞，并允许在不撕裂、不粘合的条件下连续变形，就可以忽略把手和杯口的日常用途；如果要拿它喝水，这种忽略显然就不合适了。

数学会严格区分同构、同胚、同伦等价等不同概念。同伦类型论等研究，为理解等同性、路径和高阶结构提供了丰富工具。但“一个序列有极限”不能因此直接改写为“这个序列与极限点同伦等价”；使用哪一种关系，必须给出相应对象与条件。[《同伦类型论》](https://homotopytypetheory.org/book/)

我所关心的，正是在保留与舍弃之间发生了什么。我们把许多内部变化当成一个稳定对象来使用，获得了更简洁的描述；但如果以后需要追问内部机制，被省去的内容又必须能够重新展开。抽象可以使我们前进，也可能使我们忘记自己省略了什么。''')
c.heading('一个系统开始描述自己，会发生什么')
c.src('ORIGINAL',42,start='以罗素悖论为例',end='这个集合到底包不包含自身？')
c.add('''先假定它包含自身。按照“只收录不包含自身的集合”这条规则，它就不应该被收录。再假定它不包含自身，它又正好满足收录条件，应该被收录。两条路都撞上了原来的规则。

这里的困难并不是人不够聪明，而是允许怎样构造对象、怎样谈论对象，必须有清楚的条件。不能先允许任意条件都生成一个集合，再要求这个无限制的系统永远不会发生矛盾。

日常语言中，“这句话是假的”也能使我们直观感受到自指造成的困难：若判它真，就接受了它说自己为假的内容；若判它假，又好像支持了相反判断。不过，把真假交替写成一个程序，只能得到交替的过程，不会因此自动获得量子叠加，也不会自动解决逻辑问题。

自指值得研究，并不是因为矛盾能够随意证明任何东西，而是因为它使一个系统所能表达、构造和证明的范围变得可见。Lawvere 对对角论证的研究，将若干逻辑与计算中的自指问题放进了共同的范畴论框架。这个方向给我的启发，是去寻找这些边界背后的结构，而不是只记住几个彼此孤立的悖论名字。[Lawvere：对角论证与笛卡尔闭范畴](https://www.tac.mta.ca/tac/reprints/articles/15/tr15abs.html)''')
c.src('OLD-DYNAMIC',0,start='哥德尔不完备性定理',end='动态的无穷高阶演化范畴理论？',replacements=[('哥德尔不完备性定理其实更准确的描述是，这是一个具备涌现能力的超完备动态系统','哥德尔不完备性定理所揭示的形式系统边界，使我想到另一个研究方向：能不能构造一个具备不断扩展能力的动态系统'),('这个系统一旦产生，那么其最小化的动态进化能力，总是能够保证这个系统涌现出新的不动点','设想这个系统能够在研究中不断产生新的稳定结构'),('而新的不动点则对应着某些来系统中的某个特殊的不动点结构','新的结构与已有结构发生联系'),('它具备全新的数学性质，并且对整个系统一直做数学性质复杂性的增量进化','引入新的数学性质，使整个系统能够继续扩展'),('不断地最小化演化过程，对应着不断涌现更复杂的不动点数学结构','不断寻找更简洁的构造，同时探索更复杂的数学结构'),('继续最小化的演化','继续这样的演化'),('是不是我们可以基于这些新的公理','能否据此研究新的公理和构造规则')])
c.add('''这个设想并没有取消不完备性定理。一个可以不断扩展的理论，与一个已经在固定规则内证明了一切的理论，是两件不同的事。增加规则之后，要重新研究这些规则能够做到什么、不能做到什么；新的一层也不会因为被叫作“高阶”，就天然免于自身的边界。

更有价值的问题是：当一个问题不能在当前结构里得到解答时，我们能不能清楚记录缺了什么，构造新的工具，再把新旧结构之间的关系连接起来？这样，边界就不仅是停止的地方，也成为继续研究的入口。''')
c.heading('有限的观察者，怎样面对越来越大的构造空间')
c.src('OLD-INFINITY',0,end='一种有限无穷大。',replacements=[('无穷大和无穷小这两个概念，还能够细化为不同等级的无穷大和无穷小。无穷是一个相对概念，即n1无穷大是相对于n0无穷大的n0无穷大，依次类推，我们甚至可以为有限的测度空间，定义相对于它的无穷大','我还想研究一种相对于构造能力的尺度：一个空间虽然在数学上有限，却可能远远超出某个有限系统能够逐一处理的范围'),('对于有限测度空间n，n的幂集空间，虽然只是有限的测度空间，但是它相对于构建它的n，却是','对于一个有限集合，它的幂集仍然有限，但其组合数量可以迅速增大。从原有系统实际能够处理的规模来看，我把这种落差比喻为')])
c.add('''例如，只有十个元素的集合，有一千零二十四个子集。元素增多时，子集数量按指数增加。这仍然是有限数量，却提醒我们，“能够写出构造规则”与“能够逐一展开全部结果”相差很远。研究实际的知识与智能系统时，这个差距不能被忽略。

因此，我要寻找的框架，需要同时容纳稳定的对象、发生的变化、构造的过程，以及观察者能够处理这些过程的条件。它既要说明我们怎样把复杂的世界压缩成可以理解的概念，也要说明这些概念怎样重新参与世界，构造出以前没有的东西。存在、变化和可构造性，就从这些问题中进入了理论的中心。''')
c.save({'reasoning':'变换的共同结构→运动的分段与极限→等价关系的条件→自指的构造边界→动态扩展→有限构造能力','examples':['道路连接','二分行走与时间','0.999…','泥杯与圆环','罗素集合','十个元素的幂集'],'objections':['有无穷分段为何能到达','等价是否任意','动态扩展是否推翻不完备性','有限空间为何称无穷'],'voice':'原始底稿为骨架，保留后续作者自指与相对尺度设想；错误数学等同作明确实质改写','status':'初校；实质修订保留原文差异，未声称作者已经批准全部技术订正'})
